import React, { useState } from 'react';
import { motion } from 'framer-motion';

export default function MemorialGallery() {
  const [activeFigure, setActiveFigure] = useState(null);
  const [step, setStep] = useState(0);

  const handleClick = (figure) => {
    setActiveFigure(figure);
    setStep(0);
  };

  const handleNext = () => {
    if (activeFigure && step < activeFigure.conversation.length - 1) {
      setStep(step + 1);
    }
  };

  return (
    <div className="gallery-container" style={{ textAlign: 'center' }}>
      {!activeFigure ? (
        <div style={{ display: 'flex', justifyContent: 'center', gap: '30px' }}>
          {figures.map((fig, idx) => (
            <motion.img
              key={idx}
              src={fig.image}
              alt={fig.name}
              initial={{ opacity: 0.4 }}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => handleClick(fig)}
              style={{ width: '200px', cursor: 'pointer' }}
            />
          ))}
        </div>
      ) : (
        <div>
          <motion.img
            src={activeFigure.clearImage}
            alt={activeFigure.name}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 1 }}
            style={{ width: '200px', marginBottom: '20px' }}
          />
          <div style={{ maxWidth: '400px', margin: '0 auto', fontSize: '1.2rem' }}>
            <p>👤 <strong>{activeFigure.name}</strong>:</p>
            <p style={{ fontStyle: 'italic' }}>{activeFigure.conversation[step]}</p>
            {step < activeFigure.conversation.length - 1 ? (
              <button onClick={handleNext} style={{ marginTop: '15px' }}>
                다음 말 듣기 →
              </button>
            ) : (
              <button onClick={() => setActiveFigure(null)} style={{ marginTop: '15px' }}>
                다른 인물 만나기
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const figures = [
  {
    name: '안중근',
    image: process.env.PUBLIC_URL + '/images/ahn_faded.png',
    clearImage: process.env.PUBLIC_URL + '/images/ahn_clear.png',
    conversation: [
      '나는 조국의 독립을 위해 이토 히로부미를 처단했네.',
      '그날의 총성은 대한독립 만세를 외친 울림이었지.',
      '기억해줘. 진정한 평화는 정의 위에 세워져야 하네.'
    ]
  },
  // 다른 인물들도 여기에 계속 추가
  {
    name: '유관순',
    image: process.env.PUBLIC_URL + '/images/yu_faded.png',
    clearImage: process.env.PUBLIC_URL +'/images/yu_clear.png',
    conversation: [
      '나는 3.1운동에 참여했어요. 그날, 우리는 모두 하나였죠.',
      '옥중에서도 자유를 외쳤어요. 끝까지 포기하지 않았죠.',
      '우리의 외침이 오늘의 대한민국을 만들었어요.'
    ]
  },
  {
    name: '김구',
    image: process.env.PUBLIC_URL + '/images/kim_faded.png',
    clearImage: process.env.PUBLIC_URL + '/images/kim_clear.png',
    conversation: [
      '나는 통일된 나라를 꿈꾸었네.',
      '내 소원은 오직 한 가지, 대한의 완전한 자주독립이었지.',
      '자유와 평화를 잊지 말아주게.'
    ]
  }
];


